import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.116.0';
import { CONFIG } from './config.js';

const supabase = createClient(CONFIG.supabaseUrl, CONFIG.supabasePublishableKey, {
  auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true }
});

const root = document.querySelector('#app');
const toastStack = document.createElement('div'); toastStack.className='toast-stack'; document.body.append(toastStack);
const state = {
  session:null, messages:[], accounts:[], labels:[], messageLabels:[], contacts:[], templates:[], signatures:[], settings:null,
  folder:'inbox', category:'all', activeId:null, selected:new Set(), search:'', loading:true,
  composer:null, commandOpen:false, filters:[], realtimeChannel:null
};

const NAV = [
  ['inbox','inbox','Inbox'],['starred','star','Starred'],['snoozed','schedule','Snoozed'],['sent','send','Sent'],
  ['scheduled','calendar_clock','Scheduled'],['drafts','draft','Drafts'],['archive','archive','Archive'],['spam','report','Spam'],['trash','delete','Trash']
];
const esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
const stripHtml=(html='')=>{const d=document.createElement('div');d.innerHTML=html;return(d.textContent||d.innerText||'').trim()};
const signaturePlainText=(html='')=>{const d=document.createElement('div');d.innerHTML=String(html).replace(/<br\s*\/?>/gi,'\n');return(d.textContent||d.innerText||'').trim()};
const initials=(name='')=>name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]?.toUpperCase()).join('')||'?';
const arr=v=>Array.isArray(v)?v:[];
const addresses=v=>arr(v).join(', ');
const splitAddr=v=>String(v||'').split(/[;,]/).map(x=>x.trim()).filter(Boolean);
const fmtDate=v=>{if(!v)return'';const d=new Date(v),n=new Date(),diff=n-d;if(d.toDateString()===n.toDateString())return d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});if(diff<7*864e5)return d.toLocaleDateString([], {weekday:'short'});return d.toLocaleDateString([], {day:'2-digit',month:'short'});};
const fmtFull=v=>v?new Date(v).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}):'';
const toast=(msg,icon='check_circle')=>{const el=document.createElement('div');el.className='toast';el.innerHTML=`<span class="material-symbols-rounded">${icon}</span><span>${esc(msg)}</span>`;toastStack.append(el);setTimeout(()=>el.remove(),3000)};
const icon=(name,cls='')=>`<span class="material-symbols-rounded ${cls}">${name}</span>`;
const currentUser=()=>state.session?.user;
const accountByAddress=address=>state.accounts.find(a=>a.address===address)||state.accounts.find(a=>a.is_primary)||null;
const accountForMessage=m=>state.accounts.find(a=>a.id===m?.account_id)||accountByAddress(m?.from_address);
const defaultFromAddress=()=>state.accounts.find(a=>a.address===state.settings?.default_sender_address)?.address||state.accounts.find(a=>a.is_primary)?.address||state.accounts[0]?.address||CONFIG.mailbox;
const trashDaysLeft=m=>{if(!m?.trashed_at)return 10;const ms=new Date(m.trashed_at).getTime()+10*864e5-Date.now();return Math.max(0,Math.ceil(ms/864e5));};
function updateDocumentTitle(){const n=unreadCount();document.title=n?`(${n}) FrankiFlow Mail`:'FrankiFlow Mail';}

function applyTheme(){
  const pref=state.settings?.theme||localStorage.getItem('ffmail-theme')||'system';
  const dark=pref==='dark'||(pref==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);
  document.documentElement.dataset.theme=dark?'dark':'light';
  document.body.dataset.density=state.settings?.density||'comfortable';
  document.body.dataset.showPreview=state.settings?.show_message_preview===false?'false':'true';
  document.body.dataset.previewPane=state.settings?.preview_pane||'right';
}

function loginView(message=''){
  root.innerHTML=`<section class="login"><form class="login-card" id="loginForm"><div class="login-logo mail-logo">${icon('mail')}</div><h1>FrankiFlow Mail</h1><p>A focused workspace for company communication.</p><div class="field"><label>Email</label><input id="email" type="email" value="${esc(CONFIG.mailbox)}" autocomplete="username" required></div><div class="field"><label>Password</label><input id="password" type="password" autocomplete="current-password" required></div><button class="btn-primary" type="submit">${icon('lock_open')} Sign in securely</button><div id="loginError" class="error">${esc(message)}</div></form></section>`;
  document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');const emailEl=document.querySelector('#email'),passwordEl=document.querySelector('#password'),errorEl=document.querySelector('#loginError');b.disabled=true;b.innerHTML=`${icon('progress_activity')} Signing in…`;const {error}=await supabase.auth.signInWithPassword({email:emailEl.value.trim(),password:passwordEl.value});if(error){errorEl.textContent=error.message;b.disabled=false;b.innerHTML=`${icon('lock_open')} Sign in securely`;}};
}

function count(folder){
  if(folder==='starred')return state.messages.filter(m=>m.is_starred&&m.folder!=='trash').length;
  if(folder==='snoozed')return state.messages.filter(m=>m.folder==='snoozed').length;
  return state.messages.filter(m=>m.folder===folder).length;
}
function unreadCount(){return state.messages.filter(m=>m.folder==='inbox'&&!m.is_read).length;}
function labelsFor(id){const ids=state.messageLabels.filter(x=>x.message_id===id).map(x=>x.label_id);return state.labels.filter(l=>ids.includes(l.id));}
function threadFor(m){if(state.settings?.conversation_view===false)return[m].filter(Boolean);return m?.thread_id?state.messages.filter(x=>x.thread_id===m.thread_id).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)):[m].filter(Boolean);}
function senderName(m){return m.direction==='outbound'||['sent','scheduled'].includes(m.folder)?addresses(m.to_addresses):(m.from_name||m.from_address||'Unknown');}
function effectiveFolder(m){if(m.folder==='snoozed'&&m.snoozed_until&&new Date(m.snoozed_until)<=new Date())return'inbox';return m.folder;}
function advancedMatch(m,query){
  if(!query.trim())return true;
  const tokens=query.match(/(?:[^\s"]+|"[^"]*")+/g)||[];let free=[];
  const stamp=new Date(m.received_at||m.sent_at||m.created_at||0);
  for(const raw of tokens){
    const t=raw.replace(/^"|"$/g,'');const i=t.indexOf(':');
    if(i>0){
      const k=t.slice(0,i).toLowerCase(),v=t.slice(i+1).toLowerCase();
      if(k==='from'&&!String(m.from_address||'').toLowerCase().includes(v))return false;
      if(k==='to'&&!addresses(m.to_addresses).toLowerCase().includes(v))return false;
      if(k==='subject'&&!String(m.subject||'').toLowerCase().includes(v))return false;
      if(k==='is'&&v==='unread'&&m.is_read)return false;
      if(k==='is'&&v==='read'&&!m.is_read)return false;
      if(k==='is'&&v==='starred'&&!m.is_starred)return false;
      if(k==='is'&&v==='pinned'&&!m.is_pinned)return false;
      if(k==='is'&&v==='important'&&m.priority!=='high')return false;
      if(k==='is'&&v==='muted'&&!m.is_muted)return false;
      if(k==='has'&&v==='attachment'&&!m.has_attachments)return false;
      if(k==='in'&&effectiveFolder(m)!==v)return false;
      if(k==='before'){const d=new Date(v);if(!Number.isNaN(d.getTime())&&stamp>=d)return false;}
      if(k==='after'){const d=new Date(v);if(!Number.isNaN(d.getTime())&&stamp<=d)return false;}
      if(k==='label'){const names=labelsFor(m.id).map(x=>x.name.toLowerCase());if(!names.some(x=>x.includes(v)))return false;}
      continue;
    }
    free.push(t.toLowerCase());
  }
  if(!free.length)return true;
  const hay=[m.from_address,m.from_name,m.subject,m.preview,m.text_body,...arr(m.to_addresses),...arr(m.cc_addresses)].filter(Boolean).join(' ').toLowerCase();
  return free.every(x=>hay.includes(x));
}
function currentMessages(){
  let list=state.folder==='starred'?state.messages.filter(m=>m.is_starred&&m.folder!=='trash'):state.messages.filter(m=>effectiveFolder(m)===state.folder);
  list=list.filter(m=>advancedMatch(m,state.search));
  return list.sort((a,b)=>(b.is_pinned-a.is_pinned)||new Date(b.received_at||b.sent_at||b.created_at)-new Date(a.received_at||a.sent_at||a.created_at));
}

function renderApp(){
  applyTheme();
  const user=currentUser();
  root.innerHTML=`<main class="shell">
    <aside class="sidebar">
      <div class="brand"><div class="brand-mark">${icon('mail')}</div><div class="words"><strong>FrankiFlow Mail</strong></div></div>
      <button class="compose-main" id="composeMain">${icon('edit_square')}<span class="compose-label">Compose</span></button>
      <div class="nav">${NAV.slice(0,6).map(navButton).join('')}</div>
      <div class="nav-section-title">More</div><div class="nav">${NAV.slice(6).map(navButton).join('')}</div>
      <div class="nav-section-title">Labels</div><div class="labels-scroll nav">${state.labels.map(l=>`<button class="nav-btn" data-label="${l.id}"><span class="label-dot" style="background:${esc(l.color)}"></span><span class="nav-label">${esc(l.name)}</span></button>`).join('')||`<button class="nav-btn" id="newLabel">${icon('add')}<span class="nav-label">Create label</span></button>`}</div>
      <div class="sidebar-spacer"></div>
      <div class="account-box"><div class="account-row"><div class="avatar">${initials(user?.email||'FF')}</div><div class="account-email">${esc(user?.email||CONFIG.mailbox)}</div></div><div class="account-actions"><button id="settingsBtn">Settings</button><button id="logoutBtn">Sign out</button></div></div>
    </aside>
    <section class="mail-list">
      <div class="topbar"><div class="search-wrap">${icon('search')}<input id="search" class="search" placeholder="Search mail — try from:, subject:, is:unread, has:attachment" value="${esc(state.search)}"><span class="search-kbd">/</span></div><button class="icon-btn" id="filterBtn" title="Search tips">${icon('tune')}</button><button class="icon-btn" id="notifyBtn" title="Desktop notifications">${icon(typeof Notification!=='undefined'&&Notification.permission==='granted'?'notifications_active':'notifications')}</button><button class="icon-btn" id="refreshBtn" title="Refresh">${icon('refresh')}</button><button class="icon-btn" id="themeBtn" title="Theme">${icon('dark_mode')}</button></div>
      <div class="list-heading"><div class="heading-row"><input class="check" id="selectAll" type="checkbox"><h2>${folderTitle()}</h2><span class="subtle">${currentMessages().length} messages</span></div>${state.folder==='trash'?`<div class="trash-tools"><span class="subtle">Automatically deleted after 10 days.</span><button class="btn btn-danger-soft" id="emptyTrashBtn">${icon('delete_forever')} Empty trash</button></div>`:''}</div>
      <div id="bulkMount"></div><div class="filter-hint">Tip: press <b>C</b> to compose, <b>J/K</b> to move, <b>E</b> to archive, <b>?</b> for shortcuts.</div>
      <div class="messages" id="messages"></div>
    </section>
    <section class="reader" id="reader"></section>
    <nav class="mobile-nav"><button data-mobile-folder="inbox" class="${state.folder==='inbox'?'active':''}">${icon('inbox')}Inbox</button><button data-mobile-folder="starred" class="${state.folder==='starred'?'active':''}">${icon('star')}Starred</button><button class="mobile-compose" id="mobileCompose">${icon('edit')}</button><button data-mobile-folder="sent" class="${state.folder==='sent'?'active':''}">${icon('send')}Sent</button><button id="mobileMore">${icon('menu')}More</button></nav>
  </main>`;
  wireShell();renderList();renderReader();renderBulk();
}
function navButton([id,ic,label]){const c=id==='inbox'?unreadCount():count(id);return`<button class="nav-btn ${state.folder===id?'active':''}" data-folder="${id}">${icon(ic)}<span class="nav-label">${label}</span>${c?`<span class="count">${c}</span>`:''}</button>`;}
function folderTitle(){return NAV.find(x=>x[0]===state.folder)?.[2]||'Mail';}

function wireShell(){
  document.querySelectorAll('[data-folder]').forEach(b=>b.onclick=()=>switchFolder(b.dataset.folder));
  document.querySelectorAll('[data-mobile-folder]').forEach(b=>b.onclick=()=>switchFolder(b.dataset.mobileFolder));
  document.querySelector('#composeMain').onclick=()=>openComposer();document.querySelector('#mobileCompose').onclick=()=>openComposer();
  document.querySelector('#logoutBtn').onclick=()=>supabase.auth.signOut();document.querySelector('#settingsBtn').onclick=openSettings;
  document.querySelector('#notifyBtn').onclick=requestNotifications;document.querySelector('#refreshBtn').onclick=()=>loadAll(true);document.querySelector('#themeBtn').onclick=toggleTheme;document.querySelector('#emptyTrashBtn')?.addEventListener('click',emptyTrash);
  const searchEl=document.querySelector('#search');searchEl.oninput=e=>{state.search=e.target.value;renderList();renderBulk();};
  searchEl.onkeydown=e=>{if(e.key==='Escape'){state.search='';e.target.value='';renderList();}};
  document.querySelector('#selectAll').onchange=e=>{const rows=currentMessages();state.selected.clear();if(e.target.checked)rows.forEach(m=>state.selected.add(m.id));renderList();renderBulk();};
  document.querySelector('#filterBtn').onclick=showSearchHelp;const mobileMore=document.querySelector('#mobileMore');mobileMore.onclick=()=>showPopover(mobileMore,[['Settings','settings',openSettings],['Refresh','refresh',()=>loadAll(true)],['Sign out','logout',()=>supabase.auth.signOut()]]);
  document.querySelectorAll('[data-label]').forEach(b=>b.onclick=()=>{state.search=`label:${state.labels.find(l=>l.id===b.dataset.label)?.name||''}`;switchFolder('inbox');});
  document.querySelector('#newLabel')?.addEventListener('click',()=>openLabelManager(true));
}
function switchFolder(folder){state.folder=folder;state.activeId=null;state.selected.clear();state.category='all';renderApp();}
function toggleTheme(){const cur=state.settings?.theme||'system';const next=cur==='dark'?'light':'dark';saveSettings({theme:next});}

function renderBulk(){
  const mount=document.querySelector('#bulkMount');if(!mount)return;const n=state.selected.size;if(!n){mount.innerHTML='';return;}
  if(state.folder==='trash'){
    mount.innerHTML=`<div class="bulkbar"><span class="selected-count">${n} selected</span><button class="icon-btn" data-bulk="restore" title="Restore to Inbox">${icon('restore_from_trash')}</button><button class="icon-btn btn-danger" data-bulk="deleteForever" title="Delete forever">${icon('delete_forever')}</button></div>`;
  }else{
    mount.innerHTML=`<div class="bulkbar"><span class="selected-count">${n} selected</span><button class="icon-btn" data-bulk="read" title="Mark read">${icon('mark_email_read')}</button><button class="icon-btn" data-bulk="unread" title="Mark unread">${icon('mark_email_unread')}</button><button class="icon-btn" data-bulk="archive" title="Archive">${icon('archive')}</button><button class="icon-btn" data-bulk="snooze" title="Snooze">${icon('schedule')}</button><button class="icon-btn" data-bulk="label" title="Label">${icon('label')}</button><button class="icon-btn btn-danger" data-bulk="trash" title="Trash">${icon('delete')}</button></div>`;
  }
  mount.querySelectorAll('[data-bulk]').forEach(b=>b.onclick=()=>bulkAction(b.dataset.bulk));
}
async function bulkAction(action){
  const ids=[...state.selected];if(!ids.length)return;
  if(action==='label')return openApplyLabel(ids);
  if(action==='snooze')return openSnooze(ids);
  if(action==='deleteForever'){
    return confirmPermanentDelete(ids);
  }
  const now=new Date().toISOString();let patch={updated_at:now};
  if(action==='read')patch.is_read=true;
  if(action==='unread')patch.is_read=false;
  if(action==='archive'){patch.folder='archive';patch.trashed_at=null;}
  if(action==='trash'){patch.folder='trash';patch.trashed_at=now;}
  if(action==='restore'){patch.folder='inbox';patch.trashed_at=null;}
  const {error}=await supabase.from('frankiflow_mail_messages').update(patch).in('id',ids);
  if(error)return toast(error.message,'error');state.selected.clear();toast(`${ids.length} message${ids.length>1?'s':''} updated`);await loadAll();
}

function renderList(){
  const box=document.querySelector('#messages');if(!box)return;const list=currentMessages();
  if(!list.length){box.innerHTML=`<div class="empty"><div>${icon(state.search?'search_off':'inbox')}<strong>${state.search?'No matching mail':'Nothing here'}</strong>${state.search?'Try another search or remove a filter.':'This folder is clean.'}</div></div>`;return;}
  box.innerHTML=list.map(m=>{const ls=labelsFor(m.id);const th=threadFor(m);return`<article class="mail-row ${m.is_read?'':'unread'} ${state.activeId===m.id?'active':''}" data-id="${m.id}"><input class="check row-check" type="checkbox" ${state.selected.has(m.id)?'checked':''}><button class="star-btn ${m.is_starred?'on':''}" data-star="${m.id}" title="Star">${icon(m.is_starred?'star':'star')}</button><div class="avatar">${initials(senderName(m))}</div><div class="mail-main"><div class="sender-line"><span class="sender">${esc(senderName(m))}</span>${th.length>1?`<span class="thread-count">${th.length}</span>`:''}${m.is_pinned?icon('keep','pin-on'):''}</div><div class="subject-line">${m.priority==='high'?'<span class="priority-dot" title="High priority"></span>':''}<span class="subject">${esc(m.subject||'(no subject)')}</span></div><div class="preview">${esc(m.preview||stripHtml(m.html_body)||m.text_body||'')}</div>${ls.length?`<div class="row-labels">${ls.slice(0,3).map(l=>`<span class="mini-label" style="background:${esc(l.color)}">${esc(l.name)}</span>`).join('')}</div>`:''}</div><div class="row-meta"><time class="time">${fmtDate(m.received_at||m.sent_at||m.scheduled_at||m.created_at)}</time><div class="row-icons">${m.has_attachments?icon('attach_file'):''}${m.folder==='snoozed'?icon('schedule'):''}</div></div></article>`}).join('');
  box.querySelectorAll('.mail-row').forEach(row=>row.onclick=async e=>{if(e.target.closest('.row-check,.star-btn'))return;const m=state.messages.find(x=>x.id===row.dataset.id);if(m?.folder==='drafts'||m?.direction==='draft'){openComposerFromDraft(m);return;}state.activeId=row.dataset.id;if(m&&!m.is_read&&m.direction==='inbound'&&state.settings?.mark_read_on_open!==false)await patchMessage(m.id,{is_read:true},false);renderList();renderReader();});
  box.querySelectorAll('.row-check').forEach(ch=>ch.onchange=e=>{const id=e.target.closest('.mail-row').dataset.id;e.target.checked?state.selected.add(id):state.selected.delete(id);renderBulk();});
  box.querySelectorAll('[data-star]').forEach(b=>b.onclick=async e=>{e.stopPropagation();const m=state.messages.find(x=>x.id===b.dataset.star);await patchMessage(m.id,{is_starred:!m.is_starred});});
  box.oncontextmenu=e=>{const row=e.target.closest('.mail-row');if(!row)return;e.preventDefault();const m=state.messages.find(x=>x.id===row.dataset.id);if(!m)return;const items=m.folder==='trash'?[['Restore to Inbox','restore_from_trash',()=>moveMessage(m.id,'inbox')],['Delete forever','delete_forever',()=>confirmPermanentDelete([m.id]),true]]:[['Archive','archive',()=>moveMessage(m.id,'archive')],['Labels','label',()=>openApplyLabel([m.id])],[m.is_read?'Mark unread':'Mark read',m.is_read?'mark_email_unread':'mark_email_read',()=>patchMessage(m.id,{is_read:!m.is_read})],[m.is_starred?'Unstar':'Star','star',()=>patchMessage(m.id,{is_starred:!m.is_starred})],['Delete','delete',()=>moveMessage(m.id,'trash'),true]];showContextMenu(e.clientX,e.clientY,items);};
}

function renderReader(){
  const panel=document.querySelector('#reader');if(!panel)return;const m=state.messages.find(x=>x.id===state.activeId);
  if(!m){panel.classList.remove('open');panel.innerHTML=`<div class="reader-empty"><div class="reader-empty-card">${icon('mail')}<strong>Select a conversation</strong>Read, reply, label or organize mail from here.</div></div>`;return;}
  const thread=threadFor(m),ls=labelsFor(m.id);
  panel.classList.add('open');panel.innerHTML=`<div class="reader-head"><button class="icon-btn reader-mobile-back" id="backReader">${icon('arrow_back')}</button><div class="reader-title">${esc(m.subject||'(no subject)')}</div><div class="reader-tools"><button class="icon-btn ${m.is_starred?'active':''}" id="readerStar">${icon('star')}</button><button class="icon-btn" id="readerArchive" title="Archive">${icon('archive')}</button><button class="icon-btn" id="readerSnooze" title="Snooze">${icon('schedule')}</button><button class="icon-btn" id="readerLabel" title="Label">${icon('label')}</button><button class="icon-btn" id="readerMore">${icon('more_vert')}</button></div></div><div class="reader-scroll"><div class="thread-summary"><span class="big-subject">${esc(m.subject||'(no subject)')}</span>${m.priority==='high'?`<span class="chip">${icon('priority_high')} Important</span>`:''}${ls.map(l=>`<span class="chip"><span class="label-dot" style="background:${esc(l.color)}"></span>${esc(l.name)}</span>`).join('')}</div>${thread.map(renderThreadCard).join('')}${m.folder!=='trash'?quickReplyHtml(m):''}</div>`;
  document.querySelector('#backReader').onclick=()=>panel.classList.remove('open');document.querySelector('#readerStar').onclick=()=>patchMessage(m.id,{is_starred:!m.is_starred});
  const archiveBtn=document.querySelector('#readerArchive'),snoozeBtn=document.querySelector('#readerSnooze');
  if(m.folder==='trash'){
    archiveBtn.title='Restore to Inbox';archiveBtn.innerHTML=icon('restore_from_trash');archiveBtn.onclick=()=>moveMessage(m.id,'inbox');
    snoozeBtn.title='Delete forever';snoozeBtn.innerHTML=icon('delete_forever');snoozeBtn.onclick=()=>confirmPermanentDelete([m.id]);
  }else{
    archiveBtn.onclick=()=>moveMessage(m.id,'archive');snoozeBtn.onclick=()=>openSnooze([m.id]);
  }
  document.querySelector('#readerLabel').onclick=()=>openApplyLabel([m.id]);
  const moreBtn=document.querySelector('#readerMore');
  moreBtn.onclick=()=>showPopover(moreBtn,m.folder==='trash'?
    [['Restore to Inbox','restore_from_trash',()=>moveMessage(m.id,'inbox')],['Print','print',()=>window.print()],['Delete forever','delete_forever',()=>confirmPermanentDelete([m.id]),true]]:
    [['Mark unread','mark_email_unread',()=>patchMessage(m.id,{is_read:false})],[m.is_pinned?'Unpin':'Pin','keep',()=>patchMessage(m.id,{is_pinned:!m.is_pinned})],[m.priority==='high'?'Normal priority':'High priority','priority_high',()=>patchMessage(m.id,{priority:m.priority==='high'?'normal':'high'})],['Category: Clients','group',()=>patchMessage(m.id,{category:'clients'})],['Category: Bookings','hotel',()=>patchMessage(m.id,{category:'bookings'})],['Category: Finance','payments',()=>patchMessage(m.id,{category:'finance'})],[m.folder==='spam'?'Not spam':'Move to spam',m.folder==='spam'?'inbox':'report',()=>moveMessage(m.id,m.folder==='spam'?'inbox':'spam')],['Print','print',()=>window.print()],['Delete','delete',()=>moveMessage(m.id,'trash'),true]]);
  document.querySelector('#replySend')?.addEventListener('click',()=>sendQuickReply(m));
  document.querySelector('#replyCompose')?.addEventListener('click',()=>openComposer({fromAddress:accountForMessage(m)?.address||defaultFromAddress(),to:m.reply_to||m.from_address,subject:replySubject(m.subject),thread_id:m.thread_id,in_reply_to:m.provider_message_id}));
  document.querySelector('#replyAllBtn')?.addEventListener('click',()=>{
    const own=new Set(state.accounts.map(a=>a.address.toLowerCase()));
    const primary=(m.reply_to||m.from_address||'').toLowerCase();
    const cc=[...arr(m.to_addresses),...arr(m.cc_addresses)].map(x=>String(x).trim()).filter(Boolean).filter(x=>!own.has(x.toLowerCase())&&x.toLowerCase()!==primary);
    openComposer({fromAddress:accountForMessage(m)?.address||defaultFromAddress(),to:m.reply_to||m.from_address,cc:[...new Set(cc)].join(', '),subject:replySubject(m.subject),thread_id:m.thread_id,in_reply_to:m.provider_message_id});
  });
  document.querySelector('#forwardBtn')?.addEventListener('click',()=>openComposer({subject:`Fwd: ${m.subject||''}`,text:`\n\n---------- Forwarded message ----------\nFrom: ${m.from_name||m.from_address}\nDate: ${fmtFull(m.received_at||m.created_at)}\nSubject: ${m.subject||''}\n\n${m.text_body||''}`}));
}
