  const attachButton=el.querySelector('#attachBtn'),fileInputEl=el.querySelector('#fileInput'),sendNowBtn=el.querySelector('#sendNow'),sendMenuBtn=el.querySelector('#sendMenu');attachButton.onclick=()=>fileInputEl.click();fileInputEl.onchange=()=>addFiles([...fileInputEl.files]);sendNowBtn.onclick=()=>sendComposer();sendMenuBtn.onclick=()=>showSendMenu(sendMenuBtn);
