function showSignaturePicker(anchor){const items=state.signatures.map(s=>[`${s.name}${s.is_default?' · default':''}`,'draw',()=>insertSignature(s.id)]);items.push(['Remove signature','format_clear',()=>{state.composer?.el.querySelectorAll('#cEditor .signature[data-ff-signature]').forEach(x=>x.remove());scheduleAutosave();}]);items.push(['Manage signatures','settings',()=>openSignatureManager()]);showPopover(anchor,items);}
function openSignatureManager(){
  const accountOptions=`<option value="">All senders</option>${state.accounts.map(a=>`<option value="${a.id}">${esc(a.address)}</option>`).join('')}`;
  const content=`<div class="signature-manager"><div id="signatureList">${state.signatures.map(s=>`<div class="template-item" data-sig-row="${s.id}"><div class="main"><strong>${esc(s.name)}${s.is_default?' · Default':''}</strong><small>${esc(stripHtml(s.html_body)).slice(0,80)}</small></div><button class="icon-btn" data-sig-edit="${s.id}">${icon('edit')}</button><button class="icon-btn" data-sig-delete="${s.id}">${icon('delete')}</button></div>`).join('')||'<p class="muted">No signatures yet.</p>'}</div><input id="sigId" type="hidden"><div class="settings-grid two"><div class="field"><label>Name</label><input id="sigName" placeholder="FrankiFlow standard"></div><div class="field"><label>Use for sender</label><select id="sigAccount">${accountOptions}</select></div></div><div class="field"><label>Signature design</label><div class="rich-toolbar"><button type="button" data-sig-cmd="bold">${icon('format_bold')}</button><button type="button" data-sig-cmd="italic">${icon('format_italic')}</button><button type="button" data-sig-cmd="underline">${icon('format_underlined')}</button><button type="button" data-sig-cmd="insertUnorderedList">${icon('format_list_bulleted')}</button><button type="button" id="sigLinkBtn">${icon('link')}</button><button type="button" id="sigImageBtn">${icon('image')} Logo</button><input id="sigImageInput" class="hidden" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></div><div id="sigEditor" class="signature-editor" contenteditable="true" data-placeholder="Paste a formatted signature here, or build one with the toolbar."></div><small class="muted">Formatted paste is supported. Logo images are embedded in the sent email so recipients can see them.</small></div><label class="setting-row"><div><strong>Default signature</strong><small>Insert automatically for this sender.</small></div><input id="sigDefault" type="checkbox"></label></div>`;
  openModal('Signatures',content,async modal=>{
    const id=modal.querySelector('#sigId').value,name=modal.querySelector('#sigName').value.trim(),editor=modal.querySelector('#sigEditor'),accountId=modal.querySelector('#sigAccount').value||null,isDefault=modal.querySelector('#sigDefault').checked;const html=sanitizeRichHtml(editor.innerHTML);if(!name||!stripHtml(html).trim()&&!html.includes('<img'))return toast('Add a signature name and content','warning');
    if(isDefault){let q=supabase.from('frankiflow_mail_signatures').update({is_default:false,updated_at:new Date().toISOString()}).eq('user_id',currentUser().id);q=accountId?q.eq('account_id',accountId):q.is('account_id',null);await q;}
    const row={user_id:currentUser().id,account_id:accountId,name,html_body:html,is_default:isDefault,updated_at:new Date().toISOString()};const result=id?await supabase.from('frankiflow_mail_signatures').update(row).eq('id',id):await supabase.from('frankiflow_mail_signatures').insert(row);if(result.error)return toast(result.error.message,'error');modal.closest('.modal-backdrop').remove();await loadAll();toast(id?'Signature updated':'Signature created','draw');
  },modal=>{
    const editor=modal.querySelector('#sigEditor');modal.querySelectorAll('[data-sig-cmd]').forEach(b=>b.onclick=()=>{document.execCommand(b.dataset.sigCmd,false,null);editor.focus();});modal.querySelector('#sigLinkBtn').onclick=()=>{const u=prompt('Paste link URL');if(u&&/^https?:|^mailto:/i.test(u)){document.execCommand('createLink',false,u);editor.focus();}};modal.querySelector('#sigImageBtn').onclick=()=>modal.querySelector('#sigImageInput').click();modal.querySelector('#sigImageInput').onchange=e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>1500*1024)return toast('Keep signature logos under 1.5 MB','warning');const r=new FileReader();r.onload=()=>{editor.focus();document.execCommand('insertHTML',false,`<img src="${r.result}" alt="Logo" style="max-width:220px;height:auto;display:block;margin-top:8px;margin-bottom:8px">`);};r.readAsDataURL(file);};editor.addEventListener('paste',()=>setTimeout(()=>{const clean=sanitizeRichHtml(editor.innerHTML);if(clean!==editor.innerHTML)editor.innerHTML=clean;},0));
    modal.querySelectorAll('[data-sig-edit]').forEach(b=>b.onclick=()=>{const s=state.signatures.find(x=>x.id===b.dataset.sigEdit);if(!s)return;modal.querySelector('#sigId').value=s.id;modal.querySelector('#sigName').value=s.name;modal.querySelector('#sigAccount').value=s.account_id||'';editor.innerHTML=s.html_body||'';modal.querySelector('#sigDefault').checked=s.is_default;});
    modal.querySelectorAll('[data-sig-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this signature?'))return;const {error}=await supabase.from('frankiflow_mail_signatures').delete().eq('id',b.dataset.sigDelete);if(error)return toast(error.message,'error');b.closest('[data-sig-row]')?.remove();state.signatures=state.signatures.filter(s=>s.id!==b.dataset.sigDelete);});
  });
}
function addFiles(files){const allowed=files.filter(f=>f.size<=8*1024*1024);const total=[...state.composer.files,...allowed].reduce((s,f)=>s+f.size,0);if(total>18*1024*1024)return toast('Keep total attachments under 18 MB','warning');state.composer.files.push(...allowed);if(allowed.length<files.length)toast('Files over 8 MB were skipped','warning');renderAttachments();}
function renderAttachments(){const box=state.composer?.el.querySelector('#attachmentList');if(!box)return;box.innerHTML=state.composer.files.map((f,i)=>`<span class="file-pill">${icon('description')} ${esc(f.name)} <small>${(f.size/1024/1024).toFixed(1)} MB</small><button data-file-remove="${i}">${icon('close')}</button></span>`).join('');box.querySelectorAll('[data-file-remove]').forEach(b=>b.onclick=()=>{state.composer.files.splice(+b.dataset.fileRemove,1);renderAttachments();});}
function scheduleAutosave(immediate=false){if(!state.composer)return;clearTimeout(state.composer.saveTimer);state.composer.el.querySelector('#draftStatus').textContent='Saving…';state.composer.saveTimer=setTimeout(saveDraft,immediate?0:900);}
async function saveDraft(){if(!state.composer)return;const d=composerData();if(!d)return;if(!state.composer.draftId&&!d.to.trim()&&!d.cc.trim()&&!d.bcc.trim()&&!d.subject.trim()&&!d.text.trim()){state.composer.el.querySelector('#draftStatus').textContent='Autosave on';return;}const account=accountByAddress(d.fromAddress)||await primaryAccount();const row={account_id:account.id,thread_id:d.thread_id,direction:'draft',folder:'drafts',from_address:d.fromAddress,to_addresses:splitAddr(d.to),cc_addresses:splitAddr(d.cc),bcc_addresses:splitAddr(d.bcc),subject:d.subject||'',text_body:d.text||'',html_body:d.html||'',preview:(d.text||'').replace(/\s+/g,' ').slice(0,180),is_read:true,updated_at:new Date().toISOString()};let result;if(state.composer.draftId)result=await supabase.from('frankiflow_mail_messages').update(row).eq('id',state.composer.draftId);else result=await supabase.from('frankiflow_mail_messages').insert(row).select('id').single();if(result.error)return state.composer?.el.querySelector('#draftStatus')&&(state.composer.el.querySelector('#draftStatus').textContent='Save failed');if(result.data?.id)state.composer.draftId=result.data.id;if(state.composer)state.composer.el.querySelector('#draftStatus').textContent='Saved';}
async function filePayload(){const out=[];for(const f of state.composer?.files||[]){const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});out.push({filename:f.name,content,contentType:f.type||undefined});}return out;}
async function sendComposer(scheduledAt=null){const d=composerData();if(!d?.to.trim())return toast('Add at least one recipient','warning');const b=state.composer.el.querySelector('#sendNow');b.disabled=true;b.innerHTML=`${icon('progress_activity')} Sending`;const inline=extractInlineImages(sanitizeRichHtml(d.html));d.html=inline.html;const meetingAttachment=meetingAttachmentPayload();const attachments=[...await filePayload(),...inline.attachments,...(meetingAttachment?[meetingAttachment]:[])];const ok=await sendMail({...d,scheduledAt,attachments,draft_id:state.composer.draftId});if(ok){state.composer.el.remove();state.composer=null;}else{b.disabled=false;b.innerHTML=`${icon('send')} Send`;}}
function localDateTimeValue(date){const d=new Date(date.getTime()-date.getTimezoneOffset()*60000);return d.toISOString().slice(0,16);}
function icsEscape(v=''){return String(v).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');}
function icsUtc(v){return new Date(v).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');}
function utf8Base64(text){const bytes=new TextEncoder().encode(text);let binary='';for(const b of bytes)binary+=String.fromCharCode(b);return btoa(binary);}
function meetingProviderLabel(provider){return provider==='teams'?'Microsoft Teams':provider==='zoom'?'Zoom':provider==='custom'?'Online meeting':'Meeting';}
function meetingAttachmentPayload(){
  const meeting=state.composer?.meeting;if(!meeting)return null;const d=composerData();if(!d)return null;
  const attendees=[...new Set([...splitAddr(d.to),...splitAddr(d.cc)].map(x=>x.toLowerCase()))];
  const uid=`${crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`}@frankiflow.de`;
  const description=[meeting.notes||'',meeting.joinUrl?`${meetingProviderLabel(meeting.provider)}: ${meeting.joinUrl}`:''].filter(Boolean).join('\n\n');
  const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//FrankiFlow Mail//Meeting Invitation//EN','CALSCALE:GREGORIAN','METHOD:REQUEST','BEGIN:VEVENT',`UID:${uid}`,`DTSTAMP:${icsUtc(new Date())}`,`DTSTART:${icsUtc(meeting.start)}`,`DTEND:${icsUtc(meeting.end)}`,`SUMMARY:${icsEscape(meeting.title)}`,`ORGANIZER:mailto:${icsEscape(d.fromAddress)}`];
  attendees.forEach(email=>lines.push(`ATTENDEE;ROLE=REQ-PARTICIPANT;RSVP=TRUE:mailto:${icsEscape(email)}`));
  if(meeting.location)lines.push(`LOCATION:${icsEscape(meeting.location)}`);if(meeting.joinUrl)lines.push(`URL:${icsEscape(meeting.joinUrl)}`);if(description)lines.push(`DESCRIPTION:${icsEscape(description)}`);
  lines.push('STATUS:CONFIRMED','SEQUENCE:0','END:VEVENT','END:VCALENDAR');
  const filename=`${meeting.title||'meeting'}`.replace(/[^a-z0-9_-]+/gi,'-').replace(/^-+|-+$/g,'').slice(0,60)||'meeting';
  return{filename:`${filename}.ics`,content:utf8Base64(lines.join('\r\n')),contentType:'text/calendar; charset=utf-8; method=REQUEST'};
}
function renderMeetingCard(meeting){const provider=meetingProviderLabel(meeting.provider),when=`${new Date(meeting.start).toLocaleString([], {dateStyle:'medium',timeStyle:'short'})} – ${new Date(meeting.end).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`;return`<div class="meeting-card" data-ff-meeting="true"><strong>${esc(meeting.title)}</strong><div>${icon('schedule')} ${esc(when)} · ${esc(meeting.timezone)}</div>${meeting.location?`<div>${icon('location_on')} ${esc(meeting.location)}</div>`:''}${meeting.joinUrl?`<div>${icon(meeting.provider==='teams'?'groups':'videocam')} <a href="${esc(meeting.joinUrl)}" target="_blank">Join ${esc(provider)}</a></div>`:''}${meeting.notes?`<p>${esc(meeting.notes).replace(/\n/g,'<br>')}</p>`:''}</div>`;}
function openMeetingScheduler(){
  const c=state.composer?.el;if(!c)return;const existing=state.composer?.meeting;const base=new Date(Date.now()+60*60000);base.setMinutes(Math.ceil(base.getMinutes()/30)*30,0,0);const finish=new Date(base.getTime()+30*60000);const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone||'Europe/Berlin';
  const attendees=existing?.attendees||[...new Set([...splitAddr(c.querySelector('#cTo').value),...splitAddr(c.querySelector('#cCc').value)])].join(', ');
  const content=`<div class="meeting-scheduler"><div class="meeting-hero">${icon('event')}<div><strong>Meeting invitation</strong><small>Create an .ics calendar invite and include a Teams, Zoom or other meeting link.</small></div></div><div class="field"><label>Meeting title</label><input id="meetTitle" value="${esc(existing?.title||c.querySelector('#cSubject').value||'Meeting')}"></div><div class="settings-grid two"><div class="field"><label>Starts</label><input id="meetStart" type="datetime-local" value="${esc(existing?localDateTimeValue(new Date(existing.start)):localDateTimeValue(base))}"></div><div class="field"><label>Ends</label><input id="meetEnd" type="datetime-local" value="${esc(existing?localDateTimeValue(new Date(existing.end)):localDateTimeValue(finish))}"></div></div><div class="settings-grid two"><div class="field"><label>Time zone</label><input id="meetTimezone" value="${esc(existing?.timezone||timezone)}"></div><div class="field"><label>Meeting type</label><select id="meetProvider"><option value="none">No online link</option><option value="teams">Microsoft Teams</option><option value="zoom">Zoom</option><option value="custom">Other online meeting</option></select></div></div><div class="field" id="meetingUrlField"><label>Meeting link</label><input id="meetUrl" type="url" value="${esc(existing?.joinUrl||'')}" placeholder="https://teams.microsoft.com/... or https://zoom.us/..."></div><div class="field"><label>Location</label><input id="meetLocation" value="${esc(existing?.location||'')}" placeholder="Optional physical location"></div><div class="field"><label>Attendees</label><input id="meetAttendees" value="${esc(attendees)}" placeholder="name@example.com, another@example.com"><small class="muted">Attendees are also added to the email To field if it is empty.</small></div><div class="field"><label>Notes</label><textarea id="meetNotes" rows="4" placeholder="Agenda or preparation notes">${esc(existing?.notes||'')}</textarea></div></div>`;
  openModal(existing?'Edit meeting':'Schedule meeting',content,modal=>{
    const title=modal.querySelector('#meetTitle').value.trim(),start=new Date(modal.querySelector('#meetStart').value),end=new Date(modal.querySelector('#meetEnd').value),provider=modal.querySelector('#meetProvider').value,joinUrl=modal.querySelector('#meetUrl').value.trim();if(!title)return toast('Add a meeting title','warning');if(!start.getTime()||!end.getTime()||end<=start)return toast('Meeting end time must be after the start time','warning');if(['teams','zoom','custom'].includes(provider)&&!/^https:\/\//i.test(joinUrl))return toast('Add a valid https meeting link','warning');
    const meeting={title,start:start.toISOString(),end:end.toISOString(),timezone:modal.querySelector('#meetTimezone').value.trim()||timezone,provider,joinUrl,location:modal.querySelector('#meetLocation').value.trim(),notes:modal.querySelector('#meetNotes').value.trim(),attendees:modal.querySelector('#meetAttendees').value.trim()};state.composer.meeting=meeting;
    const attendeeList=splitAddr(meeting.attendees);if(attendeeList.length&&!c.querySelector('#cTo').value.trim())c.querySelector('#cTo').value=attendeeList.join(', ');if(!c.querySelector('#cSubject').value.trim())c.querySelector('#cSubject').value=meeting.title;
    const editor=c.querySelector('#cEditor');editor.querySelectorAll('[data-ff-meeting]').forEach(x=>x.remove());editor.insertAdjacentHTML('afterbegin',`${renderMeetingCard(meeting)}<br>`);modal.closest('.modal-backdrop').remove();scheduleAutosave();toast('Meeting invitation added','event');
  },modal=>{const provider=modal.querySelector('#meetProvider'),urlField=modal.querySelector('#meetingUrlField'),url=modal.querySelector('#meetUrl');provider.value=existing?.provider||'none';const update=()=>{const online=provider.value!=='none';urlField.classList.toggle('hidden',!online);url.placeholder=provider.value==='teams'?'https://teams.microsoft.com/l/meetup-join/...':provider.value==='zoom'?'https://company.zoom.us/j/...':'https://...';};provider.onchange=update;update();});
}

function showSendMenu(anchor){showPopover(anchor,[['Send now','send',()=>sendComposer()],['Later today','schedule',()=>sendComposer(todayAt(18))],['Tomorrow morning','calendar_today',()=>sendComposer(tomorrowAt(8))],['Choose date & time','edit_calendar',()=>openSchedulePicker()]]);}
function todayAt(h){const d=new Date();d.setHours(h,0,0,0);if(d<=new Date())d.setDate(d.getDate()+1);return d.toISOString();}function tomorrowAt(h){const d=new Date();d.setDate(d.getDate()+1);d.setHours(h,0,0,0);return d.toISOString();}
function openSchedulePicker(){closePopover();const d=new Date(Date.now()+3600e3);const local=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);openModal('Schedule send',`<div class="field"><label>Send date and time</label><input id="scheduleAt" type="datetime-local" value="${local}" min="${new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}"></div>`,async modal=>{const v=modal.querySelector('#scheduleAt').value;if(!v)return;modal.closest('.modal-backdrop').remove();await sendComposer(new Date(v).toISOString());});}

async function sendMail(payload){
  try{const {data,error}=await supabase.functions.invoke('send-mail',{body:{...payload,to:splitAddr(payload.to),cc:splitAddr(payload.cc),bcc:splitAddr(payload.bcc)}});if(error)throw error;if(data?.error)throw new Error(data.error);if(payload.draft_id)await supabase.from('frankiflow_mail_messages').delete().eq('id',payload.draft_id);await rememberContacts(splitAddr(payload.to));toast(payload.scheduledAt?'Email scheduled':'Email sent',payload.scheduledAt?'schedule':'send');await loadAll();return true;}catch(e){toast(`Send failed: ${e.message}`,'error');return false;}
}
async function rememberContacts(emails){for(const email of emails){const existing=state.contacts.find(c=>c.email.toLowerCase()===email.toLowerCase());if(existing)await supabase.from('frankiflow_mail_contacts').update({use_count:(existing.use_count||0)+1,last_used_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',existing.id);else await supabase.from('frankiflow_mail_contacts').insert({email,use_count:1,last_used_at:new Date().toISOString()});}}
async function primaryAccount(){const {data,error}=await supabase.from('frankiflow_mail_accounts').select('*').eq('is_primary',true).single();if(error)throw error;return data;}

function openSnooze(ids){openModal('Snooze message',`<div class="field"><label>Bring it back</label><select id="snoozeChoice"><option value="later">Later today · 18:00</option><option value="tomorrow">Tomorrow · 08:00</option><option value="week">Next week · Monday 08:00</option><option value="custom">Choose date & time</option></select></div><div class="field hidden" id="snoozeCustomWrap"><label>Date and time</label><input id="snoozeCustom" type="datetime-local"></div>`,async modal=>{const c=modal.querySelector('#snoozeChoice').value;let d;if(c==='later')d=new Date(todayAt(18));if(c==='tomorrow')d=new Date(tomorrowAt(8));if(c==='week'){d=new Date();d.setDate(d.getDate()+((8-d.getDay())%7||7));d.setHours(8,0,0,0);}if(c==='custom')d=new Date(modal.querySelector('#snoozeCustom').value);if(!d||isNaN(d))return;const {error}=await supabase.from('frankiflow_mail_messages').update({folder:'snoozed',snoozed_until:d.toISOString(),updated_at:new Date().toISOString()}).in('id',ids);if(error)return toast(error.message,'error');modal.closest('.modal-backdrop').remove();state.selected.clear();state.activeId=null;toast('Message snoozed','schedule');await loadAll();},modal=>{modal.querySelector('#snoozeChoice').onchange=e=>modal.querySelector('#snoozeCustomWrap').classList.toggle('hidden',e.target.value!=='custom');});}

function openApplyLabel(ids){const body=`<div>${state.labels.map(l=>`<label class="label-manage-item"><input class="check label-choice" type="checkbox" value="${l.id}"><span class="label-dot" style="background:${esc(l.color)}"></span><span>${esc(l.name)}</span></label>`).join('')||'<p class="muted">No labels yet.</p>'}<button class="btn" id="manageLabelsInline">${icon('add')} Create label</button></div>`;openModal('Apply labels',body,async modal=>{const choices=[...modal.querySelectorAll('.label-choice:checked')].map(x=>x.value);for(const id of ids){for(const label_id of choices)await supabase.from('frankiflow_mail_message_labels').upsert({message_id:id,label_id},{onConflict:'message_id,label_id'});}modal.closest('.modal-backdrop').remove();toast('Labels updated','label');await loadAll();},modal=>modal.querySelector('#manageLabelsInline').onclick=()=>{modal.closest('.modal-backdrop').remove();openLabelManager(true);});}
function openLabelManager(create=false){const content=`<div id="labelList">${state.labels.map(l=>`<div class="label-manage-item"><span class="label-dot" style="background:${esc(l.color)}"></span><span style="flex:1">${esc(l.name)}</span><button class="icon-btn" data-label-delete="${l.id}">${icon('delete')}</button></div>`).join('')}</div><div class="field"><label>New label</label><input id="labelName" placeholder="e.g. Clients"><input id="labelColor" type="color" value="#155b74"></div>`;openModal('Manage labels',content,async modal=>{const name=modal.querySelector('#labelName').value.trim();if(name){const {error}=await supabase.from('frankiflow_mail_labels').insert({name,color:modal.querySelector('#labelColor').value,created_by:currentUser().id});if(error)return toast(error.message,'error');}modal.closest('.modal-backdrop').remove();await loadAll();toast(name?'Label created':'Labels saved','label');},modal=>{modal.querySelectorAll('[data-label-delete]').forEach(b=>b.onclick=async()=>{await supabase.from('frankiflow_mail_labels').delete().eq('id',b.dataset.labelDelete);b.closest('.label-manage-item').remove();});if(create)setTimeout(()=>modal.querySelector('#labelName').focus(),30);});}

function showTemplatePicker(anchor){if(!state.templates.length)return showPopover(anchor,[['No templates yet','article',()=>openTemplateManager()],['Create template','add',()=>openTemplateManager(true)]]);showPopover(anchor,[...state.templates.map(t=>[t.name,'article',()=>applyTemplate(t)]),['Manage templates','settings',()=>openTemplateManager()]]);}
function applyTemplate(t){const c=state.composer?.el;if(!c)return;c.querySelector('#cSubject').value=t.subject||c.querySelector('#cSubject').value;c.querySelector('#cEditor').innerHTML=t.html_body||esc(t.text_body||'').replace(/\n/g,'<br>');if(state.settings?.signature_enabled!==false)insertSignature();scheduleAutosave();}
function openTemplateManager(create=false){const content=`<div>${state.templates.map(t=>`<div class="template-item"><div class="main"><strong>${esc(t.name)}</strong><small>${esc(t.subject||t.text_body||'')}</small></div><button class="icon-btn" data-template-delete="${t.id}">${icon('delete')}</button></div>`).join('')}</div><div class="field"><label>Template name</label><input id="tplName" placeholder="Quote follow-up"></div><div class="field"><label>Subject</label><input id="tplSubject"></div><div class="field"><label>Message</label><textarea id="tplBody" rows="6"></textarea></div>`;openModal('Email templates',content,async modal=>{const name=modal.querySelector('#tplName').value.trim();if(name){const {error}=await supabase.from('frankiflow_mail_templates').insert({name,subject:modal.querySelector('#tplSubject').value,text_body:modal.querySelector('#tplBody').value,created_by:currentUser().id});if(error)return toast(error.message,'error');}modal.closest('.modal-backdrop').remove();await loadAll();if(name)toast('Template created','article');},modal=>{modal.querySelectorAll('[data-template-delete]').forEach(b=>b.onclick=async()=>{await supabase.from('frankiflow_mail_templates').delete().eq('id',b.dataset.templateDelete);b.closest('.template-item').remove();});if(create)setTimeout(()=>modal.querySelector('#tplName').focus(),30);});}

function openFilterManager(){
  const filters=state.filters||[];const labelOptions=`<option value="">No label</option>${state.labels.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}`;const accountOptions=`<option value="">Any receiving address</option>${state.accounts.map(a=>`<option value="${esc(a.address)}">${esc(a.address)}</option>`).join('')}`;
  const content=`<div class="filter-list">${filters.map(f=>`<div class="template-item filter-row"><div class="main"><strong>${esc(f.name)}</strong><small>${esc(filterSummary(f))}</small></div><span class="status-pill ${f.active===false?'off':''}">${f.active===false?'Paused':'Active'}</span><button class="icon-btn" data-filter-toggle="${f.id}" title="${f.active===false?'Enable':'Pause'}">${icon(f.active===false?'play_arrow':'pause')}</button><button class="icon-btn" data-filter-delete="${f.id}">${icon('delete')}</button></div>`).join('')||'<p class="muted">No filters yet. Build rules using sender, recipient, subject, body, attachments and receiving account.</p>'}</div><div class="filter-builder"><div class="field"><label>Filter name</label><input id="filterName" placeholder="Invoices from suppliers"></div><div class="filter-subhead">Match incoming mail when…</div><div class="settings-grid two"><div class="field"><label>From contains</label><input id="filterFrom" placeholder="billing@ or @supplier.com"></div><div class="field"><label>To contains</label><input id="filterTo" placeholder="accounts@client.com"></div><div class="field"><label>Subject contains</label><input id="filterSubject" placeholder="invoice"></div><div class="field"><label>Body contains</label><input id="filterBody" placeholder="payment due"></div><div class="field"><label>Received at</label><select id="filterAccount">${accountOptions}</select></div><div class="field"><label>Attachments</label><select id="filterAttachment"><option value="">Any</option><option value="yes">Has attachment</option><option value="no">No attachment</option></select></div></div><div class="filter-subhead">Then…</div><div class="settings-grid two"><div class="field"><label>Apply label</label><select id="filterLabel">${labelOptions}</select></div><div class="field"><label>Move message</label><select id="filterFolder"><option value="">Leave in Inbox</option><option value="archive">Archive</option><option value="spam">Spam</option><option value="trash">Trash</option></select></div></div><div class="filter-actions-grid"><label><input id="filterRead" type="checkbox"> Mark as read</label><label><input id="filterStar" type="checkbox"> Star</label><label><input id="filterImportant" type="checkbox"> High priority</label><label><input id="filterPin" type="checkbox"> Pin</label><label><input id="filterStop" type="checkbox"> Stop processing more filters</label></div></div>`;
  openModal('Mail filters',content,async modal=>{const name=modal.querySelector('#filterName').value.trim();if(!name)return toast('Add a filter name','warning');const conditions={from_contains:modal.querySelector('#filterFrom').value.trim(),to_contains:modal.querySelector('#filterTo').value.trim(),subject_contains:modal.querySelector('#filterSubject').value.trim(),body_contains:modal.querySelector('#filterBody').value.trim(),account_address:modal.querySelector('#filterAccount').value||'',has_attachment:modal.querySelector('#filterAttachment').value||''};if(!Object.values(conditions).some(Boolean))return toast('Add at least one matching condition','warning');const actions={};const labelId=modal.querySelector('#filterLabel').value,folder=modal.querySelector('#filterFolder').value;if(labelId)actions.label_id=labelId;if(folder)actions.folder=folder;if(modal.querySelector('#filterRead').checked)actions.is_read=true;if(modal.querySelector('#filterStar').checked)actions.is_starred=true;if(modal.querySelector('#filterImportant').checked)actions.priority='high';if(modal.querySelector('#filterPin').checked)actions.is_pinned=true;if(modal.querySelector('#filterStop').checked)actions.stop_processing=true;if(!Object.keys(actions).length)return toast('Choose at least one action','warning');const {error}=await supabase.from('frankiflow_mail_filters').insert({name,conditions,actions,created_by:currentUser().id,active:true});if(error)return toast(error.message,'error');modal.closest('.modal-backdrop').remove();await loadAll();toast('Filter created','filter_alt');},modal=>{modal.querySelectorAll('[data-filter-delete]').forEach(b=>b.onclick=async()=>{const {error}=await supabase.from('frankiflow_mail_filters').delete().eq('id',b.dataset.filterDelete);if(error)return toast(error.message,'error');b.closest('.filter-row')?.remove();state.filters=state.filters.filter(f=>f.id!==b.dataset.filterDelete);});modal.querySelectorAll('[data-filter-toggle]').forEach(b=>b.onclick=async()=>{const f=state.filters.find(x=>x.id===b.dataset.filterToggle);if(!f)return;const active=f.active===false;const {error}=await supabase.from('frankiflow_mail_filters').update({active,updated_at:new Date().toISOString()}).eq('id',f.id);if(error)return toast(error.message,'error');modal.closest('.modal-backdrop').remove();await loadAll();openFilterManager();});});
}
function filterSummary(f){const c=f.conditions||{},a=f.actions||{},parts=[];if(c.from_contains)parts.push(`from “${c.from_contains}”`);if(c.to_contains)parts.push(`to “${c.to_contains}”`);if(c.subject_contains)parts.push(`subject “${c.subject_contains}”`);if(c.body_contains)parts.push(`body “${c.body_contains}”`);if(c.account_address)parts.push(`received at ${c.account_address}`);if(c.has_attachment==='yes')parts.push('has attachment');if(c.has_attachment==='no')parts.push('no attachment');const actions=[];if(a.label_id)actions.push(`label ${state.labels.find(l=>l.id===a.label_id)?.name||'selected'}`);if(a.folder)actions.push(`move to ${a.folder}`);if(a.is_read)actions.push('mark read');if(a.is_starred)actions.push('star');if(a.priority==='high')actions.push('high priority');if(a.is_pinned)actions.push('pin');return`${parts.join(' · ')||'Any inbound mail'} → ${actions.join(', ')||'No action'}`;}
async function applyFilters(){
  if(!state.filters?.length)return;for(const m of state.messages.filter(x=>x.direction==='inbound'&&x.folder==='inbox')){for(const f of state.filters.filter(x=>x.active!==false)){const c=f.conditions||{},account=accountForMessage(m)?.address||arr(m.to_addresses)[0]||'',body=String(m.text_body||stripHtml(m.html_body)||'').toLowerCase();if(c.from_contains&&!String(m.from_address||'').toLowerCase().includes(String(c.from_contains).toLowerCase()))continue;if(c.to_contains&&![...arr(m.to_addresses),...arr(m.cc_addresses)].join(' ').toLowerCase().includes(String(c.to_contains).toLowerCase()))continue;if(c.subject_contains&&!String(m.subject||'').toLowerCase().includes(String(c.subject_contains).toLowerCase()))continue;if(c.body_contains&&!body.includes(String(c.body_contains).toLowerCase()))continue;if(c.account_address&&String(account).toLowerCase()!==String(c.account_address).toLowerCase())continue;if(c.has_attachment==='yes'&&!m.has_attachments)continue;if(c.has_attachment==='no'&&m.has_attachments)continue;const a=f.actions||{},patch={};for(const key of ['folder','is_read','is_starred','priority','is_pinned'])if(a[key]!==undefined)patch[key]=a[key];if(a.folder==='trash')patch.trashed_at=new Date().toISOString();if(Object.keys(patch).length){await supabase.from('frankiflow_mail_messages').update({...patch,updated_at:new Date().toISOString()}).eq('id',m.id);Object.assign(m,patch);}if(a.label_id){await supabase.from('frankiflow_mail_message_labels').upsert({message_id:m.id,label_id:a.label_id},{onConflict:'message_id,label_id'});if(!state.messageLabels.some(x=>x.message_id===m.id&&x.label_id===a.label_id))state.messageLabels.push({message_id:m.id,label_id:a.label_id});}if(a.stop_processing)break;}}
}
function openSettings(){const s=state.settings||{};const notificationState=typeof Notification==='undefined'?'Unsupported':Notification.permission;const accounts=state.accounts.map(a=>`<div class="account-setting-row editable" data-account-row="${a.id}"><span>${icon(a.is_primary?'mark_email_read':'alternate_email')}</span><div class="account-setting-main"><strong>${esc(a.address)}</strong><small>${a.is_primary?'Routing account · verified':'Additional account · verified'}</small><div class="account-edit-grid"><label><span>Display name</span><input class="account-display-name" data-account-address="${esc(a.address)}" value="${esc(a.display_name||'FrankiFlow')}" maxlength="80"></label><label class="account-default"><input type="radio" name="accountDefault" value="${esc(a.address)}"><span>Default sender</span></label></div></div></div>`).join('');const content=`<div class="settings-hub"><section class="settings-section"><h4>${icon('palette')} Appearance & reading</h4><div class="settings-grid two"><div class="field"><label>Theme</label><select id="setTheme"><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></div><div class="field"><label>Density</label><select id="setDensity"><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></div><div class="field"><label>Preview pane</label><select id="setPreviewPane"><option value="right">Right side</option><option value="off">Off</option></select></div><div class="field"><label>Conversation view</label><select id="setConversation"><option value="true">Group threads</option><option value="false">Single messages</option></select></div></div><label class="setting-row"><div><strong>Message preview text</strong><small>Show the first lines below each subject.</small></div><input id="setShowPreview" type="checkbox"></label><label class="setting-row"><div><strong>Mark mail read when opened</strong><small>Turn off if you prefer to mark messages manually.</small></div><input id="setMarkRead" type="checkbox"></label></section><section class="settings-section"><h4>${icon('edit_note')} Compose & reply</h4><div class="settings-grid two"><div class="field"><label>Default sender</label><select id="setDefaultSender">${state.accounts.map(a=>`<option value="${esc(a.address)}">${esc(a.address)}</option>`).join('')}</select></div><div class="field"><label>Keyboard shortcuts</label><select id="setShortcuts"><option value="true">Enabled</option><option value="false">Disabled</option></select></div></div><label class="setting-row"><div><strong>Automatic signature</strong><small>Insert the default signature for the selected sender.</small></div><input id="setSignatureEnabled" type="checkbox"></label><label class="setting-row"><div><strong>Confirm permanent deletion</strong><small>Ask before a message is deleted forever.</small></div><input id="setConfirmDelete" type="checkbox"></label></section><section class="settings-section"><h4>${icon('notifications')} Notifications</h4><label class="setting-row"><div><strong>New mail notifications</strong><small>Browser permission: ${esc(notificationState)}</small></div><input id="setNotifications" type="checkbox"></label><label class="setting-row"><div><strong>Notification sound</strong><small>Play a short tone for new inbound mail while the app is open.</small></div><input id="setNotificationSound" type="checkbox"></label><button class="btn" id="enableNotificationsBtn">${icon('notifications_active')} Request browser permission</button></section><section class="settings-section"><h4>${icon('auto_awesome')} AI writing assistant</h4><label class="setting-row"><div><strong>Enable AI assistant</strong><small>Generate, improve and translate directly in Compose with Gemini.</small></div><input id="setAiEnabled" type="checkbox"></label><div class="settings-grid three"><div class="field"><label>Model</label><select id="setAiModel"><option value="gemini-3.5-flash-lite">Gemini 3.5 Flash-Lite · low cost</option><option value="gemini-3.5-flash">Gemini 3.5 Flash · balanced</option><option value="gemini-3.8-flash">Gemini 3.8 Flash · highest quality</option></select></div><div class="field"><label>Default tone</label><select id="setAiTone"><option value="professional">Professional</option><option value="friendly">Friendly</option><option value="concise">Concise</option><option value="formal">Formal</option></select></div><div class="field"><label>Default language</label><select id="setAiLanguage"><option value="auto">Auto</option><option value="German">German</option><option value="English">English</option></select></div></div><small class="muted">Powered by Gemini. The Gemini API key is stored securely in Supabase and is never exposed to the browser.</small></section><section class="settings-section"><h4>${icon('alternate_email')} Mail accounts</h4><div class="account-settings">${accounts}</div><small class="muted">Email addresses are read-only because they are tied to DNS and Resend. You can change the sender display name and choose the default sender here. Inbound messages automatically receive an Info or Mail label based on the original address that received them.</small></section><section class="settings-section"><h4>${icon('tune')} Organization & tools</h4><div class="settings-actions"><button class="btn" id="manageSignaturesBtn">${icon('draw')} Signatures</button><button class="btn" id="manageLabelsBtn">${icon('label')} Labels</button><button class="btn" id="manageTemplatesBtn">${icon('article')} Templates</button><button class="btn" id="manageFiltersBtn">${icon('filter_alt')} Filters</button><button class="btn" id="shortcutsBtn">${icon('keyboard')} Shortcuts</button></div></section><section class="settings-section"><h4>${icon('shield')} Storage & safety</h4><div class="settings-status"><span>${icon('delete_sweep')} Trash is permanently purged after 10 days.</span><span>${icon('sync')} Live mailbox updates are enabled.</span></div></section></div>`;openModal('Settings',content,async modal=>{if(!await saveMailAccountSettings(modal))return;await saveSettings({theme:modal.querySelector('#setTheme').value,density:modal.querySelector('#setDensity').value,preview_pane:modal.querySelector('#setPreviewPane').value,conversation_view:modal.querySelector('#setConversation').value==='true',show_message_preview:modal.querySelector('#setShowPreview').checked,mark_read_on_open:modal.querySelector('#setMarkRead').checked,default_sender_address:modal.querySelector('input[name="accountDefault"]:checked')?.value||modal.querySelector('#setDefaultSender').value,keyboard_shortcuts:modal.querySelector('#setShortcuts').value==='true',signature_enabled:modal.querySelector('#setSignatureEnabled').checked,confirm_permanent_delete:modal.querySelector('#setConfirmDelete').checked,notifications_enabled:modal.querySelector('#setNotifications').checked,notification_sound:modal.querySelector('#setNotificationSound').checked,ai_enabled:modal.querySelector('#setAiEnabled').checked,ai_model:modal.querySelector('#setAiModel').value,ai_tone:modal.querySelector('#setAiTone').value,ai_language:modal.querySelector('#setAiLanguage').value});modal.closest('.modal-backdrop').remove();toast('Settings saved','settings');renderApp();},modal=>{modal.querySelector('#setTheme').value=s.theme||'system';modal.querySelector('#setDensity').value=s.density||'comfortable';modal.querySelector('#setPreviewPane').value=s.preview_pane||'right';modal.querySelector('#setConversation').value=String(s.conversation_view!==false);modal.querySelector('#setShowPreview').checked=s.show_message_preview!==false;modal.querySelector('#setMarkRead').checked=s.mark_read_on_open!==false;const configuredDefault=s.default_sender_address||defaultFromAddress();modal.querySelector('#setDefaultSender').value=configuredDefault;const defaultRadio=modal.querySelector(`input[name="accountDefault"][value="${CSS.escape(configuredDefault)}"]`);if(defaultRadio)defaultRadio.checked=true;modal.querySelectorAll('input[name="accountDefault"]').forEach(r=>r.onchange=()=>{if(r.checked)modal.querySelector('#setDefaultSender').value=r.value;});modal.querySelector('#setDefaultSender').onchange=e=>{const r=modal.querySelector(`input[name="accountDefault"][value="${CSS.escape(e.target.value)}"]`);if(r)r.checked=true;};modal.querySelector('#setShortcuts').value=String(s.keyboard_shortcuts!==false);modal.querySelector('#setSignatureEnabled').checked=s.signature_enabled!==false;modal.querySelector('#setConfirmDelete').checked=s.confirm_permanent_delete!==false;modal.querySelector('#setNotifications').checked=s.notifications_enabled!==false;modal.querySelector('#setNotificationSound').checked=s.notification_sound===true;modal.querySelector('#setAiEnabled').checked=s.ai_enabled!==false;modal.querySelector('#setAiModel').value=s.ai_model||'gemini-3.5-flash-lite';modal.querySelector('#setAiTone').value=s.ai_tone||'professional';modal.querySelector('#setAiLanguage').value=s.ai_language||'auto';modal.querySelector('#enableNotificationsBtn').onclick=requestNotifications;modal.querySelector('#manageSignaturesBtn').onclick=()=>openSignatureManager();modal.querySelector('#manageLabelsBtn').onclick=()=>openLabelManager();modal.querySelector('#manageTemplatesBtn').onclick=()=>openTemplateManager();modal.querySelector('#manageFiltersBtn').onclick=()=>openFilterManager();modal.querySelector('#shortcutsBtn').onclick=()=>showShortcuts();});}
async function edgeFunctionErrorMessage(error,data,fallback='Request failed'){
  if(data?.error)return String(data.error);
  try{if(error?.context?.clone){const payload=await error.context.clone().json();if(payload?.error)return String(payload.error);}}
  catch{}
  return error?.message||fallback;
}
async function saveMailAccountSettings(modal){
  const accounts=[...modal.querySelectorAll('.account-display-name')].map(input=>({address:input.dataset.accountAddress,display_name:input.value.trim()}));
  if(accounts.some(a=>!a.display_name)){toast('Each mail account needs a display name','warning');return false;}
  const {data,error}=await supabase.functions.invoke('mail-account-settings',{body:{accounts}});
  if(error||data?.error){toast(await edgeFunctionErrorMessage(error,data,'Could not update mail accounts'),'error');return false;}
  if(Array.isArray(data?.accounts))state.accounts=data.accounts;
  return true;
}
async function saveSettings(patch){const row={user_id:currentUser().id,...state.settings,...patch,updated_at:new Date().toISOString()};delete row.created_at;const {data,error}=await supabase.from('frankiflow_mail_settings').upsert(row,{onConflict:'user_id'}).select().single();if(error)return toast(error.message,'error');state.settings=data;applyTheme();}

function showShortcuts(){openModal('Keyboard shortcuts',`<div class="setting-row"><strong>Compose</strong><kbd>C</kbd></div><div class="setting-row"><strong>Search</strong><kbd>/</kbd></div><div class="setting-row"><strong>Next / previous message</strong><kbd>J / K</kbd></div><div class="setting-row"><strong>Archive</strong><kbd>E</kbd></div><div class="setting-row"><strong>Star</strong><kbd>S</kbd></div><div class="setting-row"><strong>Mark unread</strong><kbd>Shift + U</kbd></div><div class="setting-row"><strong>Delete</strong><kbd>#</kbd></div><div class="setting-row"><strong>Command palette</strong><kbd>Ctrl/⌘ + K</kbd></div>`,null);}
function showSearchHelp(){openModal('Power search',`<p class="muted">Combine terms to narrow the current mailbox.</p><div class="setting-row"><strong>from:alex@example.com</strong><small>Sender address</small></div><div class="setting-row"><strong>to:client@example.com</strong><small>Recipient address</small></div><div class="setting-row"><strong>subject:invoice</strong><small>Subject text</small></div><div class="setting-row"><strong>is:unread · is:starred · is:pinned · is:important</strong><small>Status</small></div><div class="setting-row"><strong>has:attachment</strong><small>Only mail with files</small></div><div class="setting-row"><strong>in:inbox · in:archive · in:trash</strong><small>Folder</small></div><div class="setting-row"><strong>before:2026-09-01 · after:2026-09-01</strong><small>Date filters</small></div><div class="setting-row"><strong>label:Clients</strong><small>Messages with a label</small></div>`,null);}
function openModal(title,body,onSave,onReady){closePopover();const back=document.createElement('div');back.className='modal-backdrop';back.innerHTML=`<section class="modal"><div class="modal-head"><h3>${esc(title)}</h3><button class="icon-btn modalClose">${icon('close')}</button></div><div class="modal-body">${body}</div>${onSave?`<div class="modal-foot"><button class="btn modalCancel">Cancel</button><button class="btn-primary modalSave">Save</button></div>`:''}</section>`;document.body.append(back);const modal=back.querySelector('.modal');back.querySelector('.modalClose').onclick=()=>back.remove();back.querySelector('.modalCancel')?.addEventListener('click',()=>back.remove());back.addEventListener('click',e=>{if(e.target===back)back.remove()});back.querySelector('.modalSave')?.addEventListener('click',()=>onSave(modal));onReady?.(modal);return modal;}

let contextMenuEl=null;
function closeContextMenu(){contextMenuEl?.remove();contextMenuEl=null;}
function showContextMenu(x,y,items){closeContextMenu();closePopover();const p=document.createElement('div');p.className='context-menu';p.innerHTML=items.map(([label,ic,,danger])=>`<button class="${danger?'danger':''}">${icon(ic)}<span>${esc(label)}</span></button>`).join('');document.body.append(p);const r=p.getBoundingClientRect();p.style.left=`${Math.min(innerWidth-r.width-8,Math.max(8,x))}px`;p.style.top=`${Math.min(innerHeight-r.height-8,Math.max(8,y))}px`;[...p.querySelectorAll('button')].forEach((b,i)=>b.onclick=()=>{closeContextMenu();items[i][2]?.();});contextMenuEl=p;setTimeout(()=>document.addEventListener('click',()=>closeContextMenu(),{once:true}),0);}
function confirmPermanentDelete(ids){if(state.settings?.confirm_permanent_delete===false)return hardDeleteMessages(ids);if(confirm(`Delete ${ids.length} message${ids.length>1?'s':''} permanently? This cannot be undone.`))return hardDeleteMessages(ids);}
function playNotificationSound(){if(state.settings?.notification_sound!==true)return;try{const C=window.AudioContext||window.webkitAudioContext;const ctx=new C(),o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=620;g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.16);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.17);}catch{}}
async function refreshMessageLabels(messageId){const {data}=await supabase.from('frankiflow_mail_message_labels').select('*').eq('message_id',messageId);state.messageLabels=state.messageLabels.filter(x=>x.message_id!==messageId);state.messageLabels.push(...(data||[]));}
let popoverEl=null;function closePopover(){popoverEl?.remove();popoverEl=null}function showPopover(anchor,items){closePopover();const r=anchor.getBoundingClientRect(),p=document.createElement('div');p.className='popover';p.innerHTML=items.map(([label,ic,,danger])=>`<button class="${danger?'danger':''}">${icon(ic)}${esc(label)}</button>`).join('');document.body.append(p);const pr=p.getBoundingClientRect();p.style.left=`${Math.min(innerWidth-pr.width-8,Math.max(8,r.right-pr.width))}px`;p.style.top=`${Math.min(innerHeight-pr.height-8,r.bottom+6)}px`;[...p.querySelectorAll('button')].forEach((b,i)=>b.onclick=()=>{closePopover();items[i][2]?.()});popoverEl=p;setTimeout(()=>document.addEventListener('click',outsidePopover,{once:true}),0)}function outsidePopover(e){if(popoverEl&&!popoverEl.contains(e.target))closePopover();}

function openCommand(){if(state.commandOpen)return;state.commandOpen=true;const back=document.createElement('div');back.className='modal-backdrop';const commands=[['Compose new email','edit_square',()=>openComposer()],['Go to Inbox','inbox',()=>switchFolder('inbox')],['Go to Sent','send',()=>switchFolder('sent')],['Go to Trash','delete',()=>switchFolder('trash')],['Search mail','search',()=>document.querySelector('#search')?.focus()],['Manage signatures','draw',()=>openSignatureManager()],['Manage labels','label',()=>openLabelManager()],['Email templates','article',()=>openTemplateManager()],['Settings','settings',()=>openSettings()],['Refresh mailbox','refresh',()=>loadAll(true)]];back.innerHTML=`<section class="modal command"><div class="command-search">${icon('search')}<input id="commandInput" placeholder="Type a command…"><kbd>Esc</kbd></div><div class="command-results">${commands.map(([n,ic])=>`<div class="command-item">${icon(ic)}<span>${esc(n)}</span></div>`).join('')}</div></section>`;document.body.append(back);const input=back.querySelector('#commandInput'),items=[...back.querySelectorAll('.command-item')];items.forEach((it,i)=>it.onclick=()=>{back.remove();state.commandOpen=false;commands[i][2]()});input.oninput=()=>items.forEach((it,i)=>it.classList.toggle('hidden',!commands[i][0].toLowerCase().includes(input.value.toLowerCase())));back.onclick=e=>{if(e.target===back){back.remove();state.commandOpen=false}};input.onkeydown=e=>{if(e.key==='Escape'){back.remove();state.commandOpen=false}};input.focus();}

function keyboardHandler(e){if(!state.session||state.commandOpen)return;const target=e.target;if(target.matches('input,textarea,[contenteditable="true"]')){if(e.key==='Escape'&&state.composer)closeComposer();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();return openCommand();}if(e.key==='/'){e.preventDefault();return document.querySelector('#search')?.focus();}if(state.settings?.keyboard_shortcuts===false)return;const k=e.key.toLowerCase();if(k==='c')return openComposer();if(k==='?')return showShortcuts();const list=currentMessages();let i=list.findIndex(m=>m.id===state.activeId);if(k==='j'){i=Math.min(list.length-1,i+1);state.activeId=list[i]?.id;renderList();renderReader();}if(k==='k'){i=Math.max(0,i<=0?0:i-1);state.activeId=list[i]?.id;renderList();renderReader();}const m=state.messages.find(x=>x.id===state.activeId);if(!m)return;if(k==='e')moveMessage(m.id,'archive');if(k==='s')patchMessage(m.id,{is_starred:!m.is_starred});if(e.shiftKey&&k==='u')patchMessage(m.id,{is_read:false});if(e.key==='#')moveMessage(m.id,'trash');}
document.addEventListener('keydown',keyboardHandler);

async function wakeSnoozed(){const due=state.messages.filter(m=>m.folder==='snoozed'&&m.snoozed_until&&new Date(m.snoozed_until)<=new Date()).map(m=>m.id);if(due.length)await supabase.from('frankiflow_mail_messages').update({folder:'inbox',snoozed_until:null,updated_at:new Date().toISOString()}).in('id',due);}
async function loadAll(showToast=false){
  if(!state.session)return;state.loading=true;
  const [m,a,l,ml,c,t,sg,s,f]=await Promise.all([
    supabase.from('frankiflow_mail_messages').select('*').order('created_at',{ascending:false}).limit(1000),
    supabase.from('frankiflow_mail_accounts').select('*').order('is_primary',{ascending:false}),
    supabase.from('frankiflow_mail_labels').select('*').order('name'),
    supabase.from('frankiflow_mail_message_labels').select('*'),
    supabase.from('frankiflow_mail_contacts').select('*').order('last_used_at',{ascending:false}).limit(200),
    supabase.from('frankiflow_mail_templates').select('*').order('name'),
    supabase.from('frankiflow_mail_signatures').select('*').order('is_default',{ascending:false}).order('name'),
    supabase.from('frankiflow_mail_settings').select('*').eq('user_id',currentUser().id).maybeSingle(),
    supabase.from('frankiflow_mail_filters').select('*').order('created_at')
  ]);
  const err=[m,a,l,ml,c,t,sg,s,f].find(x=>x.error)?.error;if(err)return toast(err.message,'error');
  state.messages=m.data||[];state.accounts=a.data||[];state.labels=l.data||[];state.messageLabels=ml.data||[];state.contacts=c.data||[];state.templates=t.data||[];state.signatures=sg.data||[];state.settings=s.data||null;state.filters=f.data||[];
  await wakeSnoozed();await applyFilters();state.loading=false;renderApp();updateDocumentTitle();if(showToast)toast('Mailbox refreshed','refresh');
}

async function requestNotifications(){if(typeof Notification==='undefined')return toast('Desktop notifications are not supported in this browser','warning');if(Notification.permission==='granted')return toast('Desktop notifications are already enabled','notifications_active');const result=await Notification.requestPermission();toast(result==='granted'?'Desktop notifications enabled':'Notifications were not enabled',result==='granted'?'notifications_active':'notifications_off');renderApp();}
function notifyNewMail(m){const who=m.from_name||m.from_address||'New sender';toast(`New mail from ${who}: ${m.subject||'(no subject)'}`,'mark_email_unread');updateDocumentTitle();playNotificationSound();if(state.settings?.notifications_enabled!==false&&typeof Notification!=='undefined'&&Notification.permission==='granted'&&(document.hidden||!document.hasFocus())){const n=new Notification(`FrankiFlow Mail · ${who}`,{body:m.subject||m.preview||'New email',icon:'/assets/icon.svg',tag:`ffmail-${m.id}`});n.onclick=()=>{window.focus();state.folder='inbox';state.activeId=m.id;renderApp();n.close();};}}
async function setupRealtime(){if(state.realtimeChannel||!state.session)return;state.realtimeChannel=supabase.channel(`frankiflow-mail-live-${currentUser().id}`).on('postgres_changes',{event:'*',schema:'public',table:'frankiflow_mail_messages'},async payload=>{if(payload.eventType==='INSERT'){const row=payload.new;if(!state.messages.some(m=>m.id===row.id))state.messages.unshift(row);await refreshMessageLabels(row.id);if(row.direction==='inbound'&&row.folder==='inbox'){notifyNewMail(row);await applyFilters();}}else if(payload.eventType==='UPDATE'){const i=state.messages.findIndex(m=>m.id===payload.new.id);if(i>=0)state.messages[i]={...state.messages[i],...payload.new};else state.messages.unshift(payload.new);}else if(payload.eventType==='DELETE'){state.messages=state.messages.filter(m=>m.id!==payload.old.id);state.messageLabels=state.messageLabels.filter(x=>x.message_id!==payload.old.id);state.selected.delete(payload.old.id);if(state.activeId===payload.old.id)state.activeId=null;}renderApp();updateDocumentTitle();}).subscribe(status=>{if(status==='CHANNEL_ERROR')toast('Live mailbox connection interrupted','warning');});}
async function teardownRealtime(){if(state.realtimeChannel){await supabase.removeChannel(state.realtimeChannel);state.realtimeChannel=null;}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateDocumentTitle();});

supabase.auth.onAuthStateChange(async(_event,session)=>{state.session=session;if(session){await loadAll();await setupRealtime();}else{await teardownRealtime();loginView();}});
const {data:{session}}=await supabase.auth.getSession();
state.session=session;
if(session){await loadAll();await setupRealtime();}else loginView();
